// Cloudflare Worker "setting-site": serves the site and receives leads.
// assets.js is generated by `node build.mjs` from index.html + images/.
import { HTML, ASSETS } from "./assets.js";

const NOTIFY_EMAIL = "yedidua1@gmail.com"; // leads are emailed here via FormSubmit
const SITE = "https://setting-site.yedidua1.workers.dev";
const TYPES = { jpg: "image/jpeg", jpeg: "image/jpeg", png: "image/png", webp: "image/webp", svg: "image/svg+xml" };

const json = (data, status = 200) =>
  new Response(JSON.stringify(data), { status, headers: { "content-type": "application/json; charset=utf-8" } });

async function sendEmail(lead) {
  const res = await fetch("https://formsubmit.co/ajax/" + NOTIFY_EMAIL, {
    method: "POST",
    headers: { "content-type": "application/json", accept: "application/json", origin: SITE, referer: SITE + "/" },
    body: JSON.stringify({
      _subject: `פנייה חדשה מהאתר: ${lead.name}`,
      _template: "table",
      _captcha: "false",
      "שם": lead.name,
      "טלפון": lead.phone,
      "תחום טיפול": lead.field || "—",
      "וואטסאפ": "https://wa.me/972" + lead.phone.replace(/\D/g, "").replace(/^0/, ""),
    }),
  });
  const body = await res.json().catch(() => ({}));
  return res.ok && String(body.success) === "true";
}

async function handleLead(request, env, ctx) {
  let data;
  try { data = await request.json(); } catch { return json({ ok: false, error: "bad_request" }, 400); }
  if (data.website) return json({ ok: true }); // honeypot: bots fill the hidden field
  const name = String(data.name || "").trim().slice(0, 120);
  const phone = String(data.phone || "").trim().slice(0, 40);
  const field = String(data.field || "").trim().slice(0, 200);
  if (name.length < 2 || phone.replace(/\D/g, "").length < 9) return json({ ok: false, error: "invalid" }, 400);

  const row = await env.DB.prepare(
    "INSERT INTO leads (name, phone, field, user_agent, country) VALUES (?, ?, ?, ?, ?) RETURNING id"
  ).bind(name, phone, field || null, request.headers.get("user-agent") || null, request.cf?.country || null).first();

  ctx.waitUntil(
    sendEmail({ name, phone, field })
      .then(ok => ok && env.DB.prepare("UPDATE leads SET email_sent = 1 WHERE id = ?").bind(row.id).run())
      .catch(() => {})
  );
  return json({ ok: true });
}

export default {
  async fetch(request, env, ctx) {
    const path = new URL(request.url).pathname;
    if (path === "/api/lead") {
      if (request.method !== "POST") return json({ ok: false, error: "method" }, 405);
      try { return await handleLead(request, env, ctx); }
      catch { return json({ ok: false, error: "server" }, 500); }
    }
    const b64 = ASSETS[path];
    if (b64) {
      const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
      return new Response(bytes, { headers: { "content-type": TYPES[path.split(".").pop().toLowerCase()] || "application/octet-stream", "cache-control": "public, max-age=86400" } });
    }
    return new Response(HTML, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "public, max-age=300" } });
  },
};
